<?php
namespace App\Domain\Clients; use App\Models\Client; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException; final class ClientManager { public function save(array $data,?Client $item,int $userId):Client{return DB::transaction(function()use($data,$item,$userId){$item??=new Client;$data['updated_by']=$userId;if(!$item->exists){$data['created_by']=$userId;$data['status']='draft';$data['display_order']=(int)Client::max('display_order')+1;}else unset($data['status']);$item->fill($data)->save();return $item;});} public function publish(Client $item):void{$this->content($item);$item->update(['status'=>'published','published_at'=>now(),'scheduled_for'=>null,'archived_at'=>null]);} public function schedule(Client $item,string $utc):void{$this->content($item);$item->update(['status'=>'scheduled','scheduled_for'=>$utc,'published_at'=>null,'archived_at'=>null]);} public function unpublish(Client $item):void{$item->update(['status'=>'draft','published_at'=>null,'scheduled_for'=>null,'archived_at'=>null]);} public function archive(Client $item):void{if(app(ClientDependencyInspector::class)->inspect($item)['blocked'])throw ValidationException::withMessages(['client'=>'Resolve active references before archiving.']);$item->update(['status'=>'archived','archived_at'=>now(),'published_at'=>null,'scheduled_for'=>null]);} public function restore(Client $item):void{$item->update(['status'=>'draft','archived_at'=>null,'published_at'=>null,'scheduled_for'=>null]);} public function duplicate(Client $item,int $userId):Client{$copy=$item->replicate(['industry_id','status','published_at','scheduled_for','archived_at','created_by','updated_by']);$copy->name.=' (Copy)';$copy->slug=$this->uniqueSlug($item->slug.'-copy');$copy->status='draft';$copy->created_by=$copy->updated_by=$userId;$copy->display_order=(int)Client::max('display_order')+1;$copy->save();return $copy;} public function move(Client $item,string $direction):void{$peer=Client::where('display_order',$direction==='up'?'<':'>',$item->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$item->display_order;$item->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}} private function uniqueSlug(string $base):string{$base=Str::slug($base)?:'client';$slug=$base;for($i=2;Client::where('slug',$slug)->exists();$i++)$slug="$base-$i";return $slug;} private function content(Client $item):void{if(!trim($item->name))throw ValidationException::withMessages(['client'=>'A name is required.']);} }
